 #include <stm32f4xx.h>
 #include <stdint.h>

int main(void)
{
    RCC->AHB1ENR |= (1<<0); // Enable GPIOA clock (Señal de reloj para GPIOA)

    GPIOA->MODER &= ~(0b11 << (5*2)); // limpiar los bits de modo para PA5 el Pin 5 de GIOA (Clear mode bits for PA5)
	GPIOA->MODER |= (0b01 << (5*2)); // Configurar PA5 como salida (Set PA5 as output) 
    GPIOA->OTYPER &= ~(1<<5); // Configurar PA5 como salida push-pull (Set PA5 as push-pull)
    
    GPIOA->OSPEEDR &= ~(0b11 << (5*2)); // Limpiar los bits de velocidad para PA5 (Clear speed bits for PA5)
    
    GPIOA->PUPDR &= ~(0b11 << (5*2)); // Limpiar los bits de pull-up/pull-down para PA5 (Clear pull-up/pull-down bits for PA5)

    //Encender el LED conectado al pin PA5:
    GPIOA->ODR &= ~(1<<5); // Limpiar posicion del registro del ODR
    GPIOA->ODR |= (1<<5); // Encender el LED (Set PA5 high)
    
    
    while (1) {

    }
    return 0;
}
